<?php declare(strict_types=1);namespace StudPulse;final class Config{private static array$values=[];public static function load(string$path):void{if(!is_file($path)){return;}foreach(file($path,FILE_IGNORE_NEW_LINES)as$line){$line=trim($line);if($line===''||str_starts_with($line,'#')){continue;}if(!preg_match('/^([A-Z][A-Z0-9_]*)=(.*)$/',$line,$m)){throw new \RuntimeException('Invalid .env syntax');}self::$values[$m[1]]=trim($m[2],"\"'");}}public static function get(string$key,string$default=''):string{$v=getenv($key);return$v!==false?$v:(self::$values[$key]??$default);}public static function bool(string$key):bool{return self::get($key)==='true';}public static function local():bool{return in_array(self::get('APP_ENV'),['development','test'],true);}public static function storage():string{$p=self::get('STORAGE_PATH','storage');return preg_match('~^(?:[A-Za-z]:[\\\\/]|/)~',$p)?$p:ROOT.'/'.$p;}public static function validate():void{if(!in_array(self::get('APP_ENV'),['development','test','staging','production'],true)){throw new \RuntimeException('APP_ENV required');}if(self::local()&&!in_array(parse_url(self::get('APP_BASE_URL'),PHP_URL_HOST),['127.0.0.1','localhost','::1','[::1]'],true)){throw new \RuntimeException('Development/test deployments must use a loopback origin');}if(self::local()&&PHP_SAPI!=='cli'&&!in_array($_SERVER['REMOTE_ADDR']??'',['127.0.0.1','::1'],true)){throw new \RuntimeException('Local environment is restricted to loopback clients');}foreach(['SESSION_SECRET','TOKEN_ENCRYPTION_KEY']as$key){$decoded=base64_decode(self::get($key),true);if($decoded===false||strlen($decoded)!==32){throw new \RuntimeException($key.' must be base64 of 32 random bytes');}}if(!str_starts_with(self::get('DATABASE_URL'),'mysql://')){throw new \RuntimeException('MySQL 8.0 DATABASE_URL required');}foreach(['SESSION_DAYS'=>[1,30],'SESSION_IDLE_DAYS'=>[1,30]]as$key=>[$min,$max]){if(!ctype_digit(self::get($key))||(int)self::get($key)<$min||(int)self::get($key)>$max){throw new \Run